#!/usr/bin/env python3
"""Writes library/NOTICE.md from library/provenance.json (rights, tier, obligations) and library/manifest.json (names, folders).
Run: python3 tools/build-notice.py [repo root]   Do not edit NOTICE.md by hand; change the register and run this again."""
import json, sys
root = sys.argv[1] if len(sys.argv) > 1 else '.'
prov = json.load(open(f'{root}/library/provenance.json')); man = {s['id']: s for s in json.load(open(f'{root}/library/manifest.json'))['sources']}
tm = prov['allowedValues']['tierMeaning']
out = ['# NOTICE: who owns what in library/', '',
 '<!-- Generated by tools/build-notice.py from library/provenance.json. Do not edit by hand. -->', '',
 'The RabbiRabbit code (everything outside `library/` and `data/`) is under the MIT licence in `LICENSE`. **The MIT licence does not cover the Bible texts, commentaries and reference works in `library/`.** Each has its own terms, listed below. Where the table says "credit required" or "share-alike", those terms travel with the material.', '',
 '## Rights tiers', '']
out += [f'- **{k}**: {v}' for k, v in tm.items()]
out += ['', 'Tiers describe how sure we are about the rights, not the quality of the work. The reasons are in `library/provenance.json`.', '']
for t in ('C', 'B', 'U', 'A'):
    rows = [s for s in prov['sources'] if s['tier'] == t]
    if not rows: continue
    out += [f'## Tier {t}', '']
    for s in rows:
        m = man.get(s['sourceId'], {}); r = s['rights']
        out.append(f"### {m.get('displayName', s['sourceId'])}  (`{m.get('folder', s['sourceId'])}`)")
        out.append(f"- Rights: {r.get('claim', 'none recorded')}")
        out.append(f"- Why this tier: {s['tierReason']}")
        for o in s.get('obligations') or []: out.append(f"- Must do: {o}")
        out.append('')
open(f'{root}/library/NOTICE.md', 'w', encoding='utf8').write('\n'.join(out))
